traps.trap01.txt:
// 切换到map049长安城

	If ($Event >= 309) @Event309; 
	
	Say("独孤剑：先救人要紧！", 1);
	Return;
	
@Event309:
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map049_长安城.map");
	LoadNpc("map049.npc");
	LoadObj("map049.obj");
	SetPlayerPos(2, 80);
	SetPlayerDir(7);
	FadeIn();
	Return;

